7	<style>
8	  :root{
9	    --bg:#f5f6f8; --panel:#ffffff; --ink:#1c2330; --ink2:#5b6472; --line:#e3e6ec;
10	    --accent:#4f46e5; --accent-soft:#eef0fe; --good:#0d9463; --good-soft:#e6f6ef;
11	    --warn:#b45309; --best:#4f46e5;
12	  }
13	  *{box-sizing:border-box;margin:0;padding:0}
14	  html,body{height:100%}
15	  body{font:13px/1.45 "Segoe UI","Microsoft YaHei",system-ui,sans-serif;background:var(--bg);color:var(--ink);
16	       display:flex;flex-direction:column;overflow:hidden}
17	
18	  /* ---------- header ---------- */
19	  header{flex:0 0 auto;display:flex;align-items:center;gap:14px;padding:10px 16px;background:var(--panel);
20	         border-bottom:1px solid var(--line)}
21	  header h1{font-size:16px;font-weight:700;letter-spacing:.5px}
22	  header .sub{color:var(--ink2);font-size:12px}
23	  .presets{display:flex;gap:6px;margin-left:auto}
24	  .preset{border:1px solid var(--line);background:#fff;border-radius:999px;padding:4px 12px;font-size:12px;
25	          color:var(--ink2);cursor:pointer}
26	  .preset:hover{border-color:var(--accent);color:var(--accent)}
27	  .verdict{display:flex;align-items:center;gap:8px;background:var(--accent-soft);border:1px solid #d8dbfb;
28	           border-radius:8px;padding:6px 12px;font-size:13px;font-weight:600;color:var(--accent)}
29	  .verdict .score{font-size:17px}
30	
31	  /* ---------- layout ---------- */
32	  main{flex:1;display:flex;min-height:0}
33	  aside{flex:0 0 292px;background:var(--panel);border-right:1px solid var(--line);display:flex;
34	        flex-direction:column;min-height:0}
35	  aside .map-head{padding:10px 14px 4px;font-size:12px;font-weight:700;color:var(--ink2);letter-spacing:1px}
36	  aside .map-wrap{flex:1;display:flex;align-items:center;justify-content:center;min-height:0}
37	  svg.map{width:100%;height:100%}
38	  .legend{flex:0 0 auto;padding:8px 14px 10px;border-top:1px solid var(--line);color:var(--ink2);font-size:11px;
39	          display:flex;flex-wrap:wrap;gap:4px 12px}
40	  .legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:4px;vertical-align:-1px}
41	
42	  section#compare{flex:1;overflow:auto;min-width:0}
43	
44	  /* ---------- comparison table ---------- */
45	  table{border-collapse:separate;border-spacing:0;width:100%;table-layout:fixed}
46	  th,td{border-bottom:1px solid var(--line);padding:0 10px;height:30px;text-align:left;overflow:hidden;
47	        white-space:nowrap;text-overflow:ellipsis}
48	  col.c0{width:236px}
49	  thead th{position:sticky;top:0;z-index:3;background:var(--panel);height:auto;padding:10px 10px 8px;
50	           border-bottom:2px solid var(--line);cursor:pointer}
51	  thead th .cand-name{font-size:14px;font-weight:700}
52	  thead th .cand-tag{display:block;color:var(--ink2);font-size:11px;font-weight:400;margin-top:1px}
53	  .rank-badge{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;
