55	  th.r1 .rank-badge{background:var(--accent);color:#fff}
56	  th.focus{outline:2px solid var(--accent);outline-offset:-2px}
57	
58	  tr.group td{background:#f0f1f5;color:var(--ink2);font-size:11px;font-weight:700;letter-spacing:1px;height:22px}
59	  td.crit{color:var(--ink);font-weight:600}
60	  td.crit small{display:block;font-weight:400;color:var(--ink2);font-size:11px}
61	  td .val{font-variant-numeric:tabular-nums}
62	  td .val em{font-style:normal;color:var(--ink2);font-size:11px;margin-left:2px}
63	  td.best .val{color:var(--best);font-weight:700}
64	  td.best{position:relative}
65	  td.best::before{content:"★";position:absolute;right:8px;top:50%;transform:translateY(-50%);
66	                  font-size:10px;color:var(--best);opacity:.85}
67	  td.col-focus{background:#fbfbff}
68	  tr:hover td:not(.crit):not(.group){background:var(--accent-soft)}
69	  tr:hover td.best{background:#e3e6fd}
70	
71	  .wcell{display:flex;align-items:center;gap:4px}
72	  .wbtn{width:18px;height:18px;border:1px solid var(--line);border-radius:4px;background:#fff;cursor:pointer;
73	        font-size:12px;line-height:1;color:var(--ink2)}
74	  .wbtn:hover{border-color:var(--accent);color:var(--accent)}
75	  .wnum{min-width:10px;text-align:center;font-weight:700;font-variant-numeric:tabular-nums}
76	  .wdots{letter-spacing:1px;color:var(--accent);font-size:9px}
77	
78	  tfoot td{position:sticky;bottom:0;background:var(--panel);height:auto;padding:8px 10px;
79	           border-top:2px solid var(--line);border-bottom:none}
80	  tfoot .total{font-size:20px;font-weight:800;font-variant-numeric:tabular-nums}
81	  tfoot .bar{height:5px;border-radius:3px;background:#edeff3;margin-top:4px;overflow:hidden}
82	  tfoot .bar i{display:block;height:100%;border-radius:3px;background:var(--accent);transition:width .2s}
83	  tfoot td.top .total{color:var(--accent)}
84	  tfoot td.top .bar i{background:linear-gradient(90deg,#4f46e5,#8b5cf6)}
85	  tfoot .vlabel{font-size:11px;color:var(--ink2)}
86	</style>
