88	<body>
89	<header>
90	  <div>
91	    <h1>栖居决策台</h1>
92	    <div class="sub">云枢科技园租房四选一 · 调整权重，比较结果即时同屏更新</div>
93	  </div>
94	  <div class="presets" id="presets"></div>
95	  <div class="verdict" id="verdict"></div>
96	</header>
97	
98	<main>
99	  <aside>
100	    <div class="map-head">地理语境 · 步行圈示意</div>
101	    <div class="map-wrap">
102	      <svg class="map" id="map" viewBox="0 0 292 470" aria-label="候选位置示意图"></svg>
103	    </div>
104	    <div class="legend">
105	      <span><i style="background:#334155"></i>公司</span>
106	      <span><i style="background:#4f46e5"></i>候选 A–D</span>
107	      <span><i style="border:1.5px dashed #94a3b8;background:none"></i>骑行 10/20/30 分钟圈</span>
108	      <span>悬停行或点列头联动 · 点击候选可聚焦</span>
109	    </div>
110	  </aside>
111	  <section id="compare"><table id="tbl"></table></section>
112	</main>
113	
114	<script>
115	"use strict";
116	
117	/* ---------------- data (inlined, first-screen ready) ---------------- */
118	const CANDS = [
119	  {id:"A", name:"桂语兰庭·东苑", tag:"3号线沿线 · 2019年小区", map:{x:78,  y:150},
120	   rent:4600, deposit:9200, area:58, metro:22, bike:18, lines:2, noise:2, light:4, floorPct:54, mkt:350, gym:1, food:3},
121	  {id:"B", name:"澜庭集公寓",     tag:"单面朝南 · 精装公寓",   map:{x:228, y:392},
122	   rent:3900, deposit:7800, area:45, metro:35, bike:28, lines:1, noise:3, light:3, floorPct:33, mkt:900, gym:0, food:4},
123	  {id:"C", name:"云栖湾公寓",     tag:"园区旁 · 高区景观",     map:{x:196, y:96},
124	   rent:5800, deposit:5800, area:72, metro:12, bike:8,  lines:3, noise:2, light:5, floorPct:69, mkt:200, gym:1, food:5},
125	  {id:"D", name:"春和景明里",     tag:"临街 · 老小区低楼层",   map:{x:112, y:300},
126	   rent:4200, deposit:8400, area:52, metro:28, bike:15, lines:2, noise:4, light:2, floorPct:17, mkt:150, gym:0, food:4},
127	];
128	
129	const CRITERIA = [
130	  {g:"成本"},
131	  {k:"rent",    label:"月租金",   unit:"¥/月", lower:true,  w:4},
132	  {k:"deposit", label:"押金",     unit:"¥",   lower:true,  w:2},
133	  {k:"area",    label:"建筑面积", unit:"m²",  lower:false, w:3},
134	  {g:"通勤"},
135	  {k:"metro",   label:"地铁通勤", unit:"min", lower:true,  w:5},
136	  {k:"bike",    label:"骑行通勤", unit:"min", lower:true,  w:3},
137	  {k:"lines",   label:"可乘线路", unit:"条",  lower:false, w:2},
138	  {g:"居住品质"},
139	  {k:"noise",   label:"噪音水平", unit:"1低–5高", lower:true,  w:3},
140	  {k:"light",   label:"采光评价", unit:"1–5",  lower:false, w:3},
141	  {k:"floorPct",label:"楼层百分位",unit:"%",   lower:false, w:1},
142	  {g:"周边配套"},
143	  {k:"mkt",     label:"最近超市", unit:"m",    lower:true,  w:2},
144	  {k:"gym",     label:"健身房",   unit:"有/无", lower:false, w:1},
145	  {k:"food",    label:"餐饮丰富度",unit:"1–5", lower:false, w:2},
146	];
147	
148	const PRESETS = {
149	  "均衡参考":  null, /* keep current */
150	  "省钱优先":  {rent:5,deposit:4,area:2,metro:2,bike:2,lines:1,noise:2,light:2,floorPct:1,mkt:3,gym:0,food:2},
151	  "通勤优先":  {rent:2,deposit:1,area:2,metro:5,bike:4,lines:3,noise:2,light:2,floorPct:1,mkt:2,gym:1,food:2},
152	  "品质优先":  {rent:2,deposit:1,area:4,metro:2,bike:2,lines:2,noise:4,light:5,floorPct:3,mkt:2,gym:3,food:4},
153	};
154	
155	/* ---------------- state ---------------- */
156	const weights = Object.fromEntries(CRITERIA.filter(c=>c.k).map(c=>[c.k,c.w]));
157	let focusId = null;
158	
159	/* ---------------- scoring ---------------- */
160	function norm(c, k, v){
161	  const vals = CANDS.map(x=>x[k]);
162	  const lo = Math.min(...vals), hi = Math.max(...vals);
163	  if (hi === lo) return 1;
164	  const t = (v - lo) / (hi - lo);
165	  return c.lower ? 1 - t : t;
166	}
167	function scores(){
168	  const out = {};
169	  let wsum = 0;
170	  for (const cand of CANDS){
171	    let s = 0; wsum = 0;
172	    for (const c of CRITERIA){
173	      if (!c.k) continue;
174	      wsum += weights[c.k];
175	      s += weights[c.k] * norm(c, c.k, cand[c.k]);
176	    }
177	    out[cand.id] = wsum ? Math.round(100 * s / wsum) : 0;
178	  }
179	  return out;
180	}
181	function bestByRow(){
182	  const best = {};
183	  for (const c of CRITERIA){
184	    if (!c.k) continue;
185	    let bi = 0;
186	    CANDS.forEach((cand,i)=>{ if (norm(c,c.k,cand[c.k]) > norm(c,c.k,CANDS[bi][c.k])) bi = i; });
187	    best[c.k] = CANDS[bi].id;
188	  }
189	  return best;
190	}
191	
192	/* ---------------- render: map ---------------- */
193	const SVGNS = "http://www.w3.org/2000/svg";
194	function el(tag, attrs, text){
195	  const n = document.createElementNS(SVGNS, tag);
196	  for (const k in attrs) n.setAttribute(k, attrs[k]);
197	  if (text != null) n.textContent = text;
198	  return n;
199	}
200	function buildMap(){
201	  const svg = document.getElementById("map");
202	  const OFF = {x:146, y:225};           /* 公司（云枢科技园） */
203	  const rings = [[10,60],[20,108],[30,156]];
204	  for (const [min,r] of rings)
205	    svg.appendChild(el("circle",{cx:OFF.x,cy:OFF.y,r,fill:"none","stroke":"#cbd5e1",
206	                                 "stroke-dasharray":"4 4","stroke-width":1.2}));
207	  /* ring labels */
208	  [[10,60],[20,108],[30,156]].forEach(([min,r])=>
209	    svg.appendChild(el("text",{x:OFF.x+4,y:OFF.y-r+11,"font-size":9,fill:"#94a3b8"}, min+"min")));
210	
211	  /* metro line 3 (stylized polyline) */
212	  svg.appendChild(el("path",{d:"M 20 190 L 78 150 L 196 96 L 258 250 L 240 420", fill:"none",
213	                             stroke:"#f59e0b","stroke-width":3,opacity:.55,"stroke-linejoin":"round"}));
214	  svg.appendChild(el("text",{x:30,y:34,"font-size":10,fill:"#b45309","font-weight":700}," Metro 3号线"));
215	
216	  /* commute links office -> candidate */
217	  for (const c of CANDS){
218	    svg.appendChild(el("line",{x1:OFF.x,y1:OFF.y,x2:c.map.x,y2:c.map.y,stroke:"#94a3b8",
219	                               "stroke-width":1,"stroke-dasharray":"2 3", class:"link-"+c.id}));
220	  }
221	  /* office marker */
222	  const g = el("g",{class:"office"});
223	  g.appendChild(el("rect",{x:OFF.x-34,y:OFF.y-13,width:68,height:26,rx:6,fill:"#334155"}));
224	  g.appendChild(el("text",{x:OFF.x,y:OFF.y+4,"text-anchor":"middle",fill:"#fff","font-size":11,
225	                           "font-weight":700},"云枢科技园"));
226	  svg.appendChild(g);
227	  /* candidate markers */
228	  for (const c of CANDS){
229	    const g = el("g",{class:"node","data-id":c.id,cursor:"pointer"});
230	    g.appendChild(el("circle",{cx:c.map.x,cy:c.map.y,r:16,fill:"#4f46e5",opacity:.16,class:"halo"}));
231	    g.appendChild(el("circle",{cx:c.map.x,cy:c.map.y,r:11,fill:"#4f46e5",stroke:"#fff","stroke-width":2}));
232	    g.appendChild(el("text",{x:c.map.x,y:c.map.y+3.5,"text-anchor":"middle",fill:"#fff","font-size":10,
233	                             "font-weight":700}, c.id));
234	    g.appendChild(el("text",{x:c.map.x+ (c.map.x>146? -18: 18), y:c.map.y+3,
235	                             "text-anchor": c.map.x>146? "end":"start","font-size":10,fill:"#475569",
236	                             "font-weight":600}, c.name.split("·")[0].split("公寓")[0]));
237	    g.appendChild(el("text",{x:c.map.x+(c.map.x>146? -18: 18), y:c.map.y+15,
238	                             "text-anchor": c.map.x>146? "end":"start","font-size":9,fill:"#64748b"},
239	                             "地铁 "+c.metro+"min"));
240	    svg.appendChild(g);
241	  }
242	}
243	
244	/* ---------------- render: table ---------------- */
245	function fmtVal(c, cand){
246	  const v = cand[c.k];
247	  if (c.k === "gym") return v ? "有" : "无";
248	  return `<span class="val">${v}<em>${c.unit}</em></span>`;
249	}
250	function buildTable(){
251	  const t = document.getElementById("tbl");
252	  let h = `<colgroup><col class="c0">${CANDS.map(()=>`<col>`).join("")}</colgroup>`;
253	  h += `<thead><tr><th class="crit">对比维度 <small>权重 ↓ 可调</small></th>${
254	    CANDS.map(c=>`<th data-id="${c.id}"><span class="rank-badge">–</span><span class="cand-name">${c.name}</span><span class="cand-tag">${c.tag}</span></th>`).join("")
255	  }</tr></thead><tbody>`;
256	  for (const c of CRITERIA){
257	    if (!c.k){ h += `<tr class="group"><td>${c.g}</td>${CANDS.map(()=>`<td></td>`).join("")}</tr>`; continue; }
258	    h += `<tr data-key="${c.k}"><td class="crit">${c.label}<small>${c.lower?"低更优":"高更优"}</small></td>${
259	      CANDS.map(cand=>`<td data-id="${cand.id}" data-key="${c.k}">${fmtVal(c,cand)}</td>`).join("")
260	    }</tr>`;
261	    /* weight stepper is inserted into the criterion cell after innerHTML */
262	  }
263	  h += `</tbody><tfoot><tr><td class="crit">加权综合得分<small>0–100 · 同屏驻留</small></td>${
264	    CANDS.map(c=>`<td data-id="${c.id}"><span class="total">–</span><div class="bar"><i></i></div><span class="vlabel"></span></td>`).join("")
265	  }</tr></tfoot>`;
266	  t.innerHTML = h;
267	
268	  /* insert weight steppers into criterion cells */
269	  for (const c of CRITERIA){
270	    if (!c.k) continue;
271	    const td = t.querySelector(`tbody tr[data-key="${c.k}"] td.crit`);
272	    const div = document.createElement("div");
273	    div.className = "wcell";
274	    div.innerHTML = `<button class="wbtn" data-k="${c.k}" data-d="-1">−</button>
275	                     <span class="wnum" data-k="${c.k}">${weights[c.k]}</span>
276	                     <button class="wbtn" data-k="${c.k}" data-d="1">＋</button>
277	                     <span class="wdots" data-k="${c.k}">${"●".repeat(weights[c.k])}</span>`;
278	    td.appendChild(div);
279	  }
280	}
281	
282	/* ---------------- update ---------------- */
283	function update(){
284	  const sc = scores(), best = bestByRow();
285	  const ranked = [...CANDS].sort((a,b)=>sc[b.id]-sc[a.id]);
286	  const top = ranked[0];
287	
288	  /* verdict pill */
289	  document.getElementById("verdict").innerHTML =
290	    `综合最优 <span class="score">${top.id}</span> ${top.name} · <span class="score">${sc[top.id]}</span> 分`;
291	
292	  /* header ranks */
293	  document.querySelectorAll("thead th[data-id]").forEach(th=>{
294	    const id = th.dataset.id;
295	    const r = ranked.findIndex(c=>c.id===id)+1;
296	    th.querySelector(".rank-badge").textContent = r===1?"①":r===2?"②":r===3?"③":"④";
297	    th.classList.toggle("r1", r===1);
