  }</tr></thead><tbody>`;
  for (const c of CRITERIA){
    if (!c.k){ h += `<tr class="group"><td>${c.g}</td>${CANDS.map(()=>`<td></td>`).join("")}</tr>`; continue; }
    h += `<tr data-key="${c.k}"><td class="crit"><div class="crow"><div class="clabel"><span>${c.label}</span><small>${c.lower?"低更优":"高更优"}</small></div></div></td>${
